# Generated by build.py from recipe.yml for recipe http-retry-through-a-busy-server. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'few', 'timed' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/report.txt'), "report ready`n")
[IO.File]::WriteAllText((Join-Path $PWD 'site/health.txt'), "up`n")
[IO.File]::WriteAllText((Join-Path $PWD 'few/report.txt'), "report ready`n")
[IO.File]::WriteAllText((Join-Path $PWD 'timed/report.txt'), "report ready`n")
[IO.File]::WriteAllText((Join-Path $PWD 'timed.sh'), "#!/bin/sh`n# Copyright (c) 2026 Stewart Rogers. Apache License 2.0. See Book/LICENSE-CODE.txt.`n# Fetches a file busy for one request with one retry after one second, and says whether the`n# whole command took at least one second and under thirty.`nstart=`$(date +%s)`ncurl -s --retry 1 --retry-delay 1 -o /dev/null `"`$1`"`nend=`$(date +%s)`nelapsed=`$((end - start))`nif [ `"`$elapsed`" -ge 1 ] && [ `"`$elapsed`" -lt 30 ]; then echo `"waited at least 1 second`"; else echo `"took `$elapsed seconds`"; fi`n")
$server0 = Start-Process surl -ArgumentList '-v', '--log-file', 'surl.log', '--directory', 'site', '--fault', '"error;scheme=http;reply=503;path=/report.txt;times=2"', 'http://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --no-progress-meter --retry 2 --retry-delay 1 -w "%{http_code} %{num_retries}\n" http://127.0.0.1:8080/report.txt } finally { Stop-Process $server0 }
